-- Do not edit this file. Any change breaks the decoder.
local _kusnou = 146
local _skkajv = 160
local _buzwnv = 130
local _gimqvd = ""

local _lbgpia = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"

local function _wumkef(a, b)
	local r, p = 0, 1
	for _ = 1, 8 do
		local x, y = a % 2, b % 2
		if x ~= y then r = r + p end
		a = (a - x) / 2; b = (b - y) / 2; p = p * 2
	end
	return r
end

local function _jlxecn(d)
	d = d:gsub("[^" .. _lbgpia .. "=]", "")
	local o = {}
	local bits = (d:gsub("[%w%+/=]", function(c)
		if c == "=" then return "" end
		local f, s = (_lbgpia:find(c, 1, true) - 1), ""
		for i = 6, 1, -1 do
			s = s .. (f % 2 ^ i - f % 2 ^ (i - 1) > 0 and "1" or "0")
		end
		return s
	end))
	local n = 0
	for i = 1, #bits - 7, 8 do
		local c = 0
		for j = 0, 7 do
			if bits:sub(i + j, i + j) == "1" then c = c + 2 ^ (7 - j) end
		end
		n = n + 1
		o[n] = string.char(c)
	end
	return table.concat(o)
end

local _tfvfee = _jlxecn(_gimqvd)
local _skbpvd = { _kusnou, _skkajv, _buzwnv }
local _xrggkl = {}
for i = 1, #_tfvfee do
	_xrggkl[i] = string.char(_wumkef(_tfvfee:byte(i), _skbpvd[(i - 1) % 3 + 1]))
end

local _ilnlrs = load or loadstring
local _vklsan, _wthyom = _ilnlrs(table.concat(_xrggkl), "=w")
if not _vklsan then
	gg.alert("Corrupted file: " .. tostring(_wthyom))
	os.exit()
end
_vklsan()
